// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // The owner (this test contract) accepts ether only in nonzero amounts:
    // a transfer of 0 to it reverts, a transfer of the positive balance succeeds.
    receive() external payable {
        require(msg.value > 0);
    }

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);

        // fund c directly through its public payable receive()
        vm.deal(address(c), amount);
        assertEq(address(c).balance, amount);

        // owner withdraws everything; the transfer amount is the deciding value
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: for every admissible (positive) balance, owner's withdrawAll
        // must succeed by transferring the full (nonzero) balance out.
        assertTrue(ok);
    }
}
